#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int i = 0, n = 0, x = 0;
    n = read();
    for (i = 0; i < n; i += 1)  {
        a[i] = read();
    }
    for (i = 0; i < n; i += 1)  {
        /* b[value] 记录该颜色数量，不交换原数组中的元素。 */
        b[a[i]] = (b[a[i]] + 1);
    }
    for (x = 0; x < 3; x += 1)  {
        for (i = 0; i < b[x]; i += 1)  {
            /* 按 0、1、2 输出各自的计数次，所以数量与输入一致且自然有序。 */
            emit(x);
        }
    }
    return 0;
}

